The detect-and-reweight paradigm~\citep{drayson2025detection} has emerged as a response to synthetic contamination in web corpora, now estimated at 20--60\% of crawled data~\citep{cheng2025contamination}.
Training on such data risks model collapse~\citep{shumailov2024model,dohmatob2025strong}, motivating methods that downweight likely-synthetic samples via $w(x) = (1 - q(x))^b$, where $q(x)$ is a detector's synthetic probability and $b$ is a sharpening exponent.
An alternative, Detect and Remove (D\&R), hard-filters samples above a threshold~\citep{feng2025beyond}.

Despite growing adoption, the paradigm's effectiveness conditions are poorly characterized.
Does D\&R genuinely outperform soft reweighting, or do published comparisons confound filtering quality with multi-epoch exposure?
What detector properties are necessary for effective reweighting?
How does the reweighting mechanism behave across contamination levels, and can $b$ be set without per-model grid search?

We investigate these questions through controlled experiments on Qwen3-0.6B continued pretraining (132M FineWeb tokens, $\rho{=}0.4$, 3 seeds), with extensions to $\rho \in \{0.2, 0.6\}$ and 1.7B parameters.
Our scope is continued pretraining with self-generated contamination; generalization to web scale, multi-source contamination, or other model families is untested (\S\ref{sec:limitations}).
To ground the analysis of exponent selection, we introduce a dual-constrained formulation: find the minimum $b$ such that $\alpha_{\mathrm{eff}}(b) \geq \tau$ (quality floor, motivated by convergence theory~\citep{wang2026survive}), subject to $\mathrm{ESS}(b) \geq n_{\min}$ (stability ceiling)~\citep{kish1965survey,vehtari2024psis}.

Our analysis yields three findings:
\begin{itemize}[nosep,leftmargin=*]
\item \textbf{Epoch confound in D\&R evaluation.}
The bulk of D\&R's PPL advantage over adaptive reweighting (${>}$95\%) is attributable to multi-epoch exposure, not filtering quality; epoch-matched controls ($N{=}3$) reduce the gap from 0.396 to $\Delta{=}0.017$ (Table~\ref{tab:epoch_match}).

\item \textbf{Detector requirements for effective reweighting.}
Both sufficient discrimination (AUC) and good calibration (ECE) are necessary; a high-AUC but poorly calibrated detector degrades performance below uniform (3 detectors, 3 seeds; \S\ref{sec:robustness}).

\item \textbf{Minimum intervention outperforms maximization.}
An $\aeff$ quality constraint binds in 38.2\% of batches at $4.9{\times}$ lower sharpening exponents than an ESS-only alternative (\S\ref{sec:regime}); at $\rho{=}0.6$, ESS-only collapses toward uniform while the dual constraint maintains its advantage.
\end{itemize}
As a practical corollary, we derive a dual-constrained adaptive $\bstar$ that eliminates per-model grid search ($\Delta{=}{-}0.020$ at $\rho{=}0.4$, $-$0.032 at $\rho{=}0.6$; Table~\ref{tab:main}), with transferable defaults ($\tau{=}0.7$, $\nmin{=}\lfloor B/2 \rfloor$).
The method fails at $\rho{=}0.2$; at 1.7B it shows no degradation but the benefit diminishes.

\begin{figure}[t]
\centering
\begin{tikzpicture}[
  node distance=0.22cm,
  topbox/.style={draw, rounded corners=2pt, fill=gray!10, text width=\columnwidth-1cm, align=center, inner sep=3pt, font=\footnotesize},
  fbox/.style={draw, rounded corners=2pt, fill=#1, text width=\columnwidth-1cm, align=left, inner sep=2.5pt, font=\scriptsize},
  botbox/.style={draw, rounded corners=2pt, fill=green!8, text width=\columnwidth-1cm, align=center, inner sep=3pt, font=\footnotesize},
  arr/.style={-{Latex[length=2mm]}, gray!60, thick}
]
\node[topbox] (top) {\textbf{Detect-and-Reweight}: $w{=}(1{-}q)^b$\quad{\scriptsize[$b$ via grid search]}};
\node[fbox=orange!8, below=of top] (f1) {\textbf{F1.} Epoch confound: ${>}$95\% of D\&R advantage over reweighting is multi-epoch exposure (\S\ref{sec:main-results})};
\node[fbox=blue!6, below=0.08cm of f1] (f2) {\textbf{F2.} Detector requirements: need both AUC \emph{and} calibration (\S\ref{sec:robustness})};
\node[fbox=violet!6, below=0.08cm of f2] (f3) {\textbf{F3.} Mechanism: minimum intervention outperforms maximization (\S\ref{sec:regime})};
\node[botbox, below=of f3] (bot) {\textbf{Adaptive $\bstar$}: dual-constrained, no grid search\quad{\scriptsize$\Delta{=}{-}0.020$}};
\draw[arr] (top) -- (f1);
\draw[arr] (f3) -- (bot);
\end{tikzpicture}
\caption{Analysis overview. We identify three effectiveness conditions for detect-and-reweight, yielding a practical adaptive method (\S\ref{sec:method}).}
\label{fig:overview}
\end{figure}

Let $\mathcal{D} = \mathcal{D}_{\mathrm{real}} \cup \mathcal{D}_{\mathrm{synth}}$ denote a pretraining corpus with token-level contamination ratio $\rho = |\mathcal{D}_{\mathrm{synth}}| / |\mathcal{D}|$, assumed unknown~\citep{cheng2025contamination}.
A detector assigns each sample $x$ a synthetic probability $q(x) \in [0,1]$; following \citet{drayson2025detection}, we weight each sample as $w(x) = (1 - q(x))^{b}$, where $b \geq 0$ is a sharpening exponent ($b{=}0$ recovers uniform training).
Rather than selecting $b$ via grid search~\citep{drayson2025detection}, we derive $b$ per-batch from the batch's $q$-score distribution using two opposing constraints.

Given a batch $\mathcal{B} = \{x_1, \ldots, x_B\}$ with scores $q_i = q(x_i)$ and weights $w_i(b) = (1 - q_i)^{b}$:

\paragraph{Quality floor.}
Let $r_i = \mathbf{1}[q_i \leq 0.5]$ indicate likely-real samples. The \emph{effective real proportion} $\aeff(b) = \sum_i w_i(b) r_i / \sum_i w_i(b)$ measures weight allocated to real samples.
We require $\aeff(b) \geq \tau$, yielding a lower bound $b_\tau$ on the exponent, motivated by convergence theory under contamination~\citep{wang2026survive}.
$\aeff$ correlates with the true batch-level real fraction at Pearson $r \approx 0.70$ (Appendix~\ref{app:alpha_validation}); limitations are discussed in \S\ref{sec:discussion}.

\paragraph{Stability ceiling.}
Kish's effective sample size $\mathrm{ESS}(b) = (\sum_i w_i)^2 / \sum_i w_i^2$~\citep{kish1965survey} decreases monotonically in $b$ (Appendix~\ref{app:proofs}).
We require $\mathrm{ESS}(b) \geq \nmin$, yielding an upper bound $\bess$.

\paragraph{Adaptive $\bstar$.}
Since $\aeff$ is non-decreasing and ESS is decreasing in $b$, the two constraints define an interval $[b_\tau, \bess]$.
The optimal exponent implements \emph{minimum intervention}:
\begin{equation}
  b^{*} = \begin{cases}
    0        & \text{if } \aeff(0) \geq \tau, \\
    b_\tau   & \text{if } b_\tau \leq \bess, \\
    \bess & \text{otherwise (stability precedence)},
  \end{cases}
  \label{eq:bstar}
\end{equation}
applying the smallest $b$ that achieves the quality floor.
Each batch falls into one of three regimes---clean, $\aeff$-binding, or ESS-binding---whose frequencies we analyze in \S\ref{sec:regime}.
Given $\bstar$, normalized weights $\pi_i = w_i(\bstar) / \sum_j w_j(\bstar)$ define the weighted loss $\mathcal{L} = \sum_i \pi_i \ell_i$; $\bstar$ is found via bisection (Algorithm~\ref{alg:bstar}, Appendix~\ref{app:algorithm}).
Defaults: $\tau{=}0.7$, $\nmin{=}\lfloor B/2 \rfloor$; sensitivity in \S\ref{sec:sensitivity}.

\section{Proofs}
\label{app:proofs}

\begin{proposition}[$\alpha_{\mathrm{eff}}$ monotonicity]
\label{prop:monotone}
$\alpha_{\mathrm{eff}}(b)$ is non-decreasing in $b$, and strictly increasing whenever the batch contains at least one sample with $q_i \in (0,1)$ and $r_i$ is not constant.
\end{proposition}

\begin{proof}[Proof of Proposition~\ref{prop:monotone}]
Let $w_i(b) = (1 - q_i)^b$, $W(b) = \sum_{j=1}^B w_j(b)$, and $\pi_i(b) = w_i(b) / W(b)$.
Then
\begin{equation*}
  \alpha_{\mathrm{eff}}(b) = \sum_{i=1}^{B} \pi_i(b)\, r_i,
\end{equation*}
where $r_i \in \{0, 1\}$ indicates whether sample $i$ is real.
Taking the derivative with respect to $b$:
\begin{align*}
  \frac{d\pi_i}{db}
  &= \pi_i \!\left(\frac{d \ln w_i}{db} - \frac{d \ln W}{db}\right) \\
  &= \pi_i \!\left(\ln(1{-}q_i) - \textstyle\sum_j \pi_j \ln(1{-}q_j)\right).
\end{align*}
Substituting,
\begin{align*}
  \frac{d\alpha_{\mathrm{eff}}}{db}
  &= \sum_i r_i\, \pi_i \!\left(\ln(1{-}q_i) - \mathbb{E}_{\pi}[\ln(1{-}q)]\right) \\
  &= \mathrm{Cov}_{\pi}\!\bigl(r_i,\, \ln(1{-}q_i)\bigr).
\end{align*}
Since $r_i = \mathbf{1}[q_i \leq 0.5]$, the indicator $r_i$ and $\ln(1{-}q_i)$ are positively associated by construction, so the covariance is non-negative.
\end{proof}

\begin{proposition}[ESS monotonicity]
\label{prop:ess_mono}
$\mathrm{ESS}(b)$ is non-increasing in $b$, and strictly decreasing whenever the batch contains at least two samples with distinct $q$-values.
\end{proposition}

\begin{proof}
Write $\mathrm{ESS}(b) = 1 / \sum_i \pi_i(b)^2$, where $\pi_i(b) = w_i(b) / W(b)$.
The denominator $\sum_i \pi_i^2$ is the Herfindahl index $H$.
Differentiating $H$ with respect to $b$:
\begin{equation*}
  \frac{dH}{db} = 2 \sum_i \pi_i^2 \bigl(\ln(1{-}q_i) - \mathbb{E}_{\pi}[\ln(1{-}q)]\bigr).
\end{equation*}
Since $\pi_i \propto (1{-}q_i)^b$, larger $\pi_i$ implies larger $\ln(1{-}q_i)$; the $\pi^2$-weighted sum assigns greater mass to terms where $\ln(1{-}q_i) > \mathbb{E}_\pi[\ln(1{-}q)]$, so $dH/db \geq 0$, with strict inequality when at least two $q$-values differ.
Thus $H$ is non-decreasing and $\mathrm{ESS} = 1/H$ is non-increasing.
This is a standard property of exponential tilting~\citep{kish1965survey,owen2013mc}.
\end{proof}

\section{Algorithm Pseudocode}
\label{app:algorithm}

\begin{algorithm}[h]
\caption{Per-batch adaptive $b^{*}$ selection}
\label{alg:bstar}
\begin{algorithmic}[1]
\REQUIRE Batch scores $\{q_i\}_{i=1}^{B}$, indicators $\{r_i\}$, quality threshold~$\tau$, ESS floor~$n_{\min}$, search bound~$b_{\max}$, tolerance~$\varepsilon$
\ENSURE Optimal sharpening exponent $b^{*}$
\IF{$\alpha_{\mathrm{eff}}(0) \geq \tau$}
  \STATE \textbf{return} $0$ \COMMENT{clean batch}
\ENDIF
\STATE $b_\tau \gets \textsc{Bisect}(\alpha_{\mathrm{eff}}(\cdot){=}\tau,\; [0, b_{\max}],\; \varepsilon)$
\IF{$\mathrm{ESS}(b_\tau) \geq n_{\min}$}
  \STATE \textbf{return} $b_\tau$ \COMMENT{$\alpha_{\mathrm{eff}}$-binding}
\ELSE
  \STATE $b_{\mathrm{ESS}} \gets \textsc{Bisect}(\mathrm{ESS}(\cdot){=}n_{\min},\; [0, b_{\max}],\; \varepsilon)$
  \STATE \textbf{return} $b_{\mathrm{ESS}}$ \COMMENT{ESS-binding}
\ENDIF
\end{algorithmic}
\end{algorithm}

Each bisection requires $\mathcal{O}(B \log(b_{\max}/\varepsilon))$ operations; with $B{=}4$, $b_{\max}{=}20$, $\varepsilon{=}0.01$, roughly 44 floating-point operations per batch, negligible beside the forward and backward passes.
We compute $\bstar$ at the micro-batch level ($B{=}4$) rather than the effective batch ($B{=}16$ after gradient accumulation) because $q$-score statistics exhibit sufficient variance within micro-batches: Spearman $r{=}0.699$ with the true real fraction, and at $B{=}16$ the adaptive advantage amplifies $3.4{\times}$ ($\Delta{=}{-}0.068{\pm}0.005$; \S\ref{sec:sensitivity}).

