\begin{tabular}{@{}lcccc@{}}
\toprule
\textbf{Method} & \textbf{Seed} & \textbf{FineWeb} $\downarrow$ & \textbf{OWT} $\downarrow$ & \textbf{Wiki} $\downarrow$ \\
\midrule
Uniform          & 42  & 17.422 & -- & -- \\
Adaptive $\bstar$ & 42  & 17.422 & -- & -- \\
\midrule
Uniform          & 123 & 17.433 & -- & -- \\
Adaptive $\bstar$ & 123 & 17.435 & -- & -- \\
\midrule
$\Delta$ (mean)  & --  & $+$0.001 & $+$0.016 & $-$0.036 \\
\bottomrule
\end{tabular}
\caption{Results at $\rho{=}0.3$ (Qwen3-0.6B, 2 seeds).
Holdout $\Delta \approx 0$ (within cross-seed noise); OOD results are mixed in direction.}
\label{tab:rho03}
